code.cpp:
class Solution {
public:
    bool areNumbersAscending(string s) {
        int prev = -1;
        int n = s.size();
        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && s[j] != ' ') j++;
            if (s[i] >= '0' && s[i] <= '9') {
                int val = 0;
                for (int k = i; k < j; k++) {
                    val = val * 10 + (s[k] - '0');
                }
                if (val <= prev) return false;
                prev = val;
            }
            i = j + 1;
        }
        return true;
    }
};
